using Aurora.Core;
using Aurora.Editor;
using System.Buffers.Binary;
static class MaterialPropertyChecks
{
 public static void Run(Action<bool,string> check,Action<Action,string> reject)
 {
  string text="$SUBMATERIAL Paint\n$DIFFUSECOLOR 1.0 0.5 0.25 1 // keep\n$CUSTOMVECTOR 3 1 2 3\n$SUBMATERIAL Window\n$DIFFUSECOLOR 0 0 0 1\n$END\n";check(NativeMaterialText.SetProperty(text,"Paint","DIFFUSECOLOR",[1,.5f,.25f,1])==text,"unchanged native material property retains exact formatting and unknown vectors");string changed=NativeMaterialText.SetProperty(text,"Paint","DIFFUSECOLOR",[.2f,.3f,.4f,1]);check(NativeMaterialText.Property(changed,"Paint","DIFFUSECOLOR")!.SequenceEqual(new float[]{.2f,.3f,.4f,1})&&changed.Contains("// keep")&&changed.Contains("$CUSTOMVECTOR 3 1 2 3")&&NativeMaterialText.Property(changed,"Window","DIFFUSECOLOR")!.SequenceEqual(new float[]{0,0,0,1}),"native color edit is scoped to its material and preserves trailing comments");changed=NativeMaterialText.SetProperty(text,"Paint","SPECULARPOWER",[64]);check(NativeMaterialText.Property(changed,"Paint","SPECULARPOWER")!.Single()==64&&!changed.Contains("\nend\n"),"missing native property inserts without terminating later materials");reject(()=>NativeMaterialText.SetProperty(text,"Paint","DIFFUSECOLOR",[float.NaN,0,0,1]),"nonfinite native material color");
  string aligned=NativeMaterialText.AlignNames("$SUBMATERIAL old\n$TEXTURE_MTL 0 paint.dds\n$END\n",new[]{"Paint"});check(aligned.Contains("$SUBMATERIAL Paint")&&aligned.Contains("$TEXTURE_MTL 0 paint.dds"),"native material slot alias aligns to NMF while preserving properties");reject(()=>NativeMaterialText.AlignNames("$SUBMATERIAL B\n$SUBMATERIAL A\n$SUBMATERIAL old\n$END\n",new[]{"A","B","C"}),"ambiguous partial material slot mapping");
  var image=new RgbaImage(3,5,Enumerable.Repeat(new byte[]{128,128,255,255},15).SelectMany(p=>p).ToArray());byte[] mip=DdsImage.Encode(image,mipmaps:true,normalMap:true);check(BinaryPrimitives.ReadInt32LittleEndian(mip.AsSpan(28))==3&&mip.Length==128+60+8+4&&DdsImage.Decode(mip).Pixels.SequenceEqual(image.Pixels),"odd-size DDS mip chain has valid count, lengths and unchanged base level");check(mip[^4]==128&&mip[^3]==128&&mip[^2]==255,"normal-map mip filtering retains normalized flat normals");byte[] gamma=DdsImage.Encode(new(2,1,[0,0,0,255,255,255,255,255]),mipmaps:true,srgb:true);check(gamma[^4] is >=187 and <=188&&gamma[^1]==255,"color mipmaps average in linear light and preserve alpha");
  var option=ObjTextureMap.Parse("-s 2 3 1 -clamp off -bm 0.5 -o -1 0.25 \"paint file.dds\"");check(option.File=="paint file.dds"&&option.Scale==new System.Numerics.Vector2(2,3)&&option.Offset==new System.Numerics.Vector2(-1,.25f)&&option.Bump==.5f&&option.Warnings.Length==0,"OBJ texture options support arbitrary order, negative offsets and quoted filenames");
  reject(()=>ObjTextureMap.Parse("-s NaN texture.dds"),"nonfinite texture scale");reject(()=>ObjTextureMap.Parse("-unknown 1 texture.dds"),"unknown map options");
  var flatNormal=DdsImage.NormalFromHeight(new(2,2,Enumerable.Repeat(new byte[]{80,80,80,255},4).SelectMany(v=>v).ToArray()));check(Enumerable.Range(0,4).All(i=>flatNormal.Pixels[i*4]==128&&flatNormal.Pixels[i*4+1]==128&&flatNormal.Pixels[i*4+2]==255),"height map conversion creates tangent normal map instead of using grayscale normals");
  var uvModel=ObjImporter.Parse("v 0 0 0\nv 1 0 0\nv 0 1 0\nvt .25 .5\nvn 0 0 1\nusemtl A\nf 1/1/1 2/1/1 3/1/1\nusemtl B\nf 1/1/1 2/1/1 3/1/1\n");var uvChanged=ModelEditing.TransformUv(uvModel.Model,new Dictionary<string,System.Numerics.Vector4>{{"A",new(2,3,-1,.25f)}});var node=uvChanged.Nodes.Single();check(node.VertexCount==6&&MathF.Abs(node.Uv[0]+.5f)<1e-5f&&MathF.Abs(node.Uv[1]+.75f)<1e-5f&&node.Uv[6]==.25f&&node.Uv[7]==.5f,"material UV transform preserves other material vertices and OBJ V convention");check(ObjImporter.Parse("v 0 0 0\nv 1 0 0\nv 0 1 0\nf 1 2 3\n").MissingUvCorners==3,"missing OBJ texture coordinates are reported");
  string root=Path.Combine(Path.GetTempPath(),"Aurora-material-values-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string mtl=Path.Combine(root,"paint.mtl");File.WriteAllText(mtl,"newmtl Paint\nKd .2 .3 .4\nKs .1 .2 .3\nKa .5 .6 .7\nNs 64\n");var model=ObjImporter.Parse("mtllib paint.mtl\nv 0 0 0\nv 1 0 0\nv 0 1 0\nusemtl Paint\nf 1 2 3\n");var values=MaterialDocuments.Obj(Path.Combine(root,"model.obj"),model)["Paint"];check(values.NativeDiffuse!.SequenceEqual(new float[]{.2f,.3f,.4f,1})&&values.NativePower==64&&values.NativeSpecular![0]==.1f,"OBJ materials without texture maps retain color and shininess");}finally{Directory.Delete(root,true);}
 }
}
